python3 - <<'PY'
import pathlib
p = pathlib.Path('src/ir_lower/expr/closures.rs')
t = p.read_text()

old_block = '''            let php_type_override = if by_ref && self_ref_callable_capture == Some(capture.as_str()) {'''
new_block = '''            // Binding a name by reference CREATES it, so there is no read to warn about and
            // nothing uninitialized to load: `$f = function () use (&$x) { ... };` leaves `$x`
            // as NULL with no diagnostic at all — MEASURED on `php -n` 8.5.6, against the
            // by-VALUE spelling one line above it, which does warn. Without the store the
            // capture reached the backend as an `undefined_local_read`, which has no
            // by-reference form and refused the program.
            //
            // It runs BEFORE the widening below for the same reason `$x = null;` written by
            // hand does: the store is what an unwritten name's creation looks like, and the
            // widening is the separate rule about what the closure may put back through the
            // reference. Boxing it here instead left `var_dump($x)` printing the raw null
            // sentinel as `int(9223372036854775806)`.
            if by_ref && ctx.local_name_is_undefined(capture) {
                let null = lower_null(ctx, expr);
                ctx.store_local(capture, null, PhpType::Void, Some(expr.span));
            }
            let php_type_override = if by_ref && self_ref_callable_capture == Some(capture.as_str()) {'''
assert t.count(old_block) == 1
t = t.replace(old_block, new_block)

old_insert = '''            // Binding a name by reference CREATES it, so there is no read to warn about and
            // nothing uninitialized to load: `$f = function () use (&$x) { ... };` leaves `$x`
            // as NULL with no diagnostic at all — MEASURED on `php -n` 8.5.6, against the
            // by-VALUE spelling one line above it, which does warn. Without the store the
            // capture reached the backend as an `undefined_local_read`, which has no
            // by-reference form and refused the program.
            if by_ref && ctx.local_name_is_undefined(capture) {
                // Boxed, and the slot widened to match: a reference has no type of its own, so
                // whatever the closure stores through it is what the outer scope reads back.
                // A raw null in an unwidened slot came back as `int(9223372036854775806)`.
                let null = lower_boxed_null(ctx, expr);
                ctx.set_local_type(capture, PhpType::Mixed);
                ctx.store_local(capture, null, PhpType::Mixed, Some(expr.span));
            }
            let captured = ctx.load_local(capture, Some(expr.span));'''
new_insert = '''            let captured = ctx.load_local(capture, Some(expr.span));'''
assert t.count(old_insert) == 1
t = t.replace(old_insert, new_insert)
p.write_text(t)
print('closures.rs: the by-ref creation store now mirrors a hand-written `$x = null;`')
